using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var noteStore = new NoteStore();

IChatClient chatClient = new OpenAI.Chat.ChatClient("gpt-4o-mini-2024-07-18", apiKey)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(noteStore.SaveNote),
    AIFunctionFactory.Create(noteStore.GetNotes),
};

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [.. tools],
};

var systemPrompt = """
    You are a research agent. Your goal is to research a topic thoroughly and produce
    a well-organized summary.

    You have access to these tools:
    1. **SearchAsync** — search the web for information on a query.
    2. **SaveNote** — save an important finding as a note for later reference.
    3. **GetNotes** — retrieve all previously saved notes.

    Follow this workflow:
    1. Search for the topic from multiple angles (at least 2-3 different searches).
    2. Save the most important findings as notes using SaveNote.
    3. After gathering enough information, retrieve all your notes with GetNotes.
    4. Produce a final, well-structured summary with key findings and sources.

    Be thorough but concise.
    """;

List<ChatMessage> messages =
[
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
];

Console.WriteLine("Agent is researching (this may take a moment)...\n");

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("════════════════════════════════════════");
Console.WriteLine("  RESEARCH SUMMARY");
Console.WriteLine("════════════════════════════════════════\n");
Console.WriteLine(response);

if (noteStore.Notes.Count > 0)
{
    Console.WriteLine("\n────────────────────────────────────────");
    Console.WriteLine("  COLLECTED NOTES");
    Console.WriteLine("────────────────────────────────────────");
    foreach (var (note, i) in noteStore.Notes.Select((n, i) => (n, i)))
    {
        Console.WriteLine($"  {i + 1}. {note}");
    }
}

// --- Tool definitions ---

public static class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a given query. Returns a summary of search results.")]
    public static async Task<string> SearchAsync(
        [Description("The search query string")] string query)
    {
        try
        {
            var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1&skip_disambig=1";
            var json = await Http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            var abstractText = root.GetProperty("AbstractText").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"[{abstractSource}] {abstractText} (Source: {abstractUrl})");
            }

            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add($"- {text} (URL: {firstUrl})");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try rephrasing the search.";
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }
}

public class NoteStore
{
    private readonly List<string> _notes = [];

    public IReadOnlyList<string> Notes => _notes;

    [Description("Save an important finding or piece of information as a note for later reference.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note saved (total: {_notes.Count}).";
    }

    [Description("Retrieve all previously saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

